package com.lqq.supportflow.eventing.application;
import com.lqq.supportflow.eventing.domain.*; import org.springframework.stereotype.Service;
@Service public class DispatchOutboxService { private final OutboxPort outbox; private final OutboxDeliveryGateway delivery; public DispatchOutboxService(OutboxPort outbox,OutboxDeliveryGateway delivery){this.outbox=outbox;this.delivery=delivery;} public int dispatch(int limit){int published=0;for(OutboxEvent event:outbox.pending(limit)){try{delivery.publish(event);outbox.markPublished(event.id());published++;}catch(RuntimeException exception){outbox.recordFailure(event.id(),failureReason(exception));}}return published;} private String failureReason(RuntimeException exception){String message=exception.getMessage();return message==null?exception.getClass().getSimpleName():message.substring(0,Math.min(500,message.length()));}}
